use crate::indicators::Format;

#[derive(Debug, Clone, Default)]
pub struct ProgressTracker {
    stages: Vec<String>,
    progress: u64,
    total: u64,
}

impl ProgressTracker {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn add_stage<S>(&mut self, stage: S) -> &mut Self
    where
        S: Into<String>,
    {
        self.stages.push(stage.into());
        self
    }

    pub fn set_progress(&mut self, progress: u64) -> &mut Self {
        self.progress = progress;
        self
    }

    pub fn set_total(&mut self, total: u64) -> &mut Self {
        self.total = total;
        self
    }

    pub fn get_progress(&self) -> String {
        format!("{}/{}", self.progress, self.total)
    }

    pub fn get_percentage(&self) -> String {
        let ratio = if self.total == 0 {
            0.0_f32
        } else {
            self.progress as f32 / self.total as f32
        };
        Format::percentage(ratio)
    }
}

#[cfg(test)]
mod tests {
    use super::ProgressTracker;

    #[test]
    fn reports_expected_progress_and_percentage() {
        let mut tracker = ProgressTracker::new();
        tracker
            .add_stage("Downloading")
            .add_stage("Processing")
            .add_stage("Saving");
        tracker.set_progress(1).set_total(3);

        assert_eq!(tracker.get_progress(), "1/3");
        assert_eq!(tracker.get_percentage(), "33.3%");
    }
}

